        /* Program Timeline */
        .timeline {
            position: relative;
            max-width: 800px;
            margin: 0 auto;
        }

        .timeline::before {
            content: '';
            position: absolute;
            width: 2px;
            background-color: var(--gold);
            top: 0;
            bottom: 0;
            left: 50%;
            margin-left: -1px;
