        const totalDisplay = document.getElementById('total');
        const selectedTierDisplay = document.getElementById('selected-tier');

        // Initialize
        document.addEventListener('DOMContentLoaded', () => {
            // Sticky Navbar
            window.addEventListener('scroll', () => {
                if (window.scrollY > 100) {
                    navbar.classList.add('scrolled');
                } else {
                    navbar.classList.remove('scrolled');
                }
            });

            // Mobile Menu
            hamburger.addEventListener('click', () => {
                hamburger.classList.toggle('active');
                navLinks.classList.toggle('active');
            });

            // Smooth Scroll
            document.querySelectorAll('a[href^="#"]').forEach(anchor => {
                anchor.addEventListener('click', function(e) {
                    e.preventDefault();
                    const targetId = this.getAttribute('href');
                    const targetElement = document.querySelector(targetId);
                    if (targetElement) {
                        window.scrollTo({
                            top: targetElement.offsetTop - 80,
                            behavior: 'smooth'
                        });
                    }
                    // Update active nav link
                    document.querySelectorAll('.nav-links a').forEach(link => {
                        link.classList.remove('active');
                    });
                    this.classList.add('active');
                    // Close mobile menu
                    hamburger.classList.remove('active');
                    navLinks.classList.remove('active');
                });
            });

            // Active Nav State
            const observer = new IntersectionObserver((entries) => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        const id = entry.target.getAttribute('id');
                        document.querySelectorAll('.nav-links a').forEach(link => {
                            link.classList.remove('active');
                            if (link.getAttribute('href') === '#' + id) {
                                link.classList.add('active');
                            }
                        });
                    }
                });
            }, { threshold: 0.5 });

            sections.forEach(section => {
                observer.observe(section);
            });

            // Scroll Reveal
            const revealObserver = new IntersectionObserver((entries) => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        entry.target.classList.add('visible');
                    }
                });
            }, { threshold: 0.1 });

            fadeIns.forEach(item => {
                revealObserver.observe(item);
            });

            // Artist Modal
            artistCards.forEach(card => {
                card.addEventListener('click', () => {
                    const id = card.getAttribute('data-id');
                    const artists = [
                        { name: 'Elara Voss', role: 'Sound installation artist', bio: 'Elara Voss is a renowned sound artist whose work explores the emotional resonance of space through layered ambient compositions. Her installations have been featured at Tate Modern, the Louvre, and the Venice Biennale.', session: '21:00 — Live Ambient Performance' },
                        { name: 'Diego Mendez', role: 'Projection mapping designer', bio: 'Diego Mendez transforms architectural surfaces into dynamic narratives using real-time projection mapping. His work merges classical art with digital technology to create immersive storytelling experiences.', session: '22:00 — Sculpture Hall Projection' },
                        { name: 'Li Wei', role: 'Contemporary sculptor', bio: 'Li Wei creates large-scale sculptures from reclaimed materials, exploring themes of memory and impermanence. Her work has been exhibited in major museums across Asia and Europe.', session: '19:30 — Curator Welcome' },
                        { name: 'Isabella Rossi', role: 'Curator & historian', bio: 'Isabella Rossi specializes in 19th-century European art history. As head curator of The Old Gallery, she has curated over 20 groundbreaking exhibitions and authored three acclaimed books.', session: '19:30 — Curator Welcome' },
                        { name: 'Ryo Nakamura', role: 'Experimental composer', bio: 'Ryo Nakamura composes minimalist soundscapes that blend traditional Japanese instruments with electronic textures. His recent work, "Silent Galleries," was commissioned by the Museum of Modern Art.', session: '01:00 — Closing Sound Session' },
                        { name: 'Kenji Tanaka', role: 'Performance artist', bio: 'Kenji Tanaka uses his body as a medium to explore cultural identity and ritual. His performances often involve long durations and audience participation, creating intimate, transformative experiences.', session: '23:00 — Artist Talk' },
                        { name: 'Maya Chen', role: 'Lighting designer', bio: 'Maya Chen designs lighting environments that enhance emotional narratives in art spaces. Her work for ARTIFACT: Museum Night uses programmable spotlights to create "golden hour" effects throughout the night.', session: 'All night' },
                        { name: 'Samir Khan', role: 'Archivist & digital historian', bio: 'Samir Khan specializes in digital preservation of cultural artifacts. He has led projects to digitize rare manuscripts and has developed AI tools for artifact classification and restoration.', session: '20:00 — Hidden Collection Tour' }
                    ];
                    const artist = artists[id];
                    document.getElementById('modal-title').textContent = artist.name;
                    document.getElementById('modal-image').src = artistCards[id].querySelector('img').src;
                    document.getElementById('modal-bio').textContent = artist.bio;
                    document.getElementById('modal-session').textContent = artist.session;
                    modal.style.display = 'block';
                });
            });

            modalClose.addEventListener('click', () => {
                modal.style.display = 'none';
            });

            window.addEventListener('click', (e) => {
                if (e.target === modal) {
                    modal.style.display = 'none';
                }
            });

            document.addEventListener('keydown', (e) => {
                if (e.key === 'Escape') {
                    modal.style.display = 'none';
                    ticketModal.style.display = 'none';
                }
            });

            // Ticket Modal
            selectBtns.forEach(btn => {
                btn.addEventListener('click', () => {
                    const tier = btn.getAttribute('data-tier');
                    const tierNames = {
                        night: 'Night Pass',
                        curator: 'Curator Pass',
                        patron: 'Patron Pass'
                    };
                    const tierPrices = {
                        night: 29,
                        curator: 59,
                        patron: 129
                    };
                    selectedTierDisplay.textContent = tierNames[tier];
                    updateTotal();
                    ticketModal.style.display = 'block';
                });
            });

            ticketModalClose.addEventListener('click', () => {
                ticketModal.style.display = 'none';
            });

            confirmBtn.addEventListener('click', () => {
                const name = nameInput.value.trim();
                const email = emailInput.value.trim();
                const tickets = ticketsSelect.value;
                const terms = document.getElementById('terms').checked;

                // Validation
                let isValid = true;
                if (!name) {
                    nameInput.classList.add('error');
                    isValid = false;
                } else {
                    nameInput.classList.remove('error');
                }

                if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
                    emailInput.classList.add('error');
                    isValid = false;
                } else {
                    emailInput.classList.remove('error');
                }

                if (!terms) {
                    toast.className = 'toast error';
                    toast.textContent = 'Please accept the Terms & Conditions';
                    toast.classList.add('show');
                    setTimeout(() => {
                        toast.classList.remove('show');
                    }, 3000);
                    return;
                }

                if (isValid) {
                    // Mock reservation
                    toast.className = 'toast success';
                    toast.textContent = 'Reservation confirmed! Check your email for details.';
                    toast.classList.add('show');
                    setTimeout(() => {
                        toast.classList.remove('show');
                    }, 3000);
                    ticketModal.style.display = 'none';
                    nameInput.value = '';
                    emailInput.value = '';
                    document.getElementById('terms').checked = false;
                }
            });

            ticketsSelect.addEventListener('change', updateTotal);
            function updateTotal() {
                const tier = selectedTierDisplay.textContent === 'Night Pass' ? 'night' :
                            selectedTierDisplay.textContent === 'Curator Pass' ? 'curator' : 'patron';
                const tierPrices = {
                    night: 29,
                    curator: 59,
                    patron: 129
                };
                const price = tierPrices[tier];
                const tickets = parseInt(ticketsSelect.value);
                totalDisplay.value = `€${(price * tickets).toFixed(2)}`;
            }

            // Save to Calendar
            saveToCalendarBtn.addEventListener('click', () => {
                const icsContent = `BEGIN:VCALENDAR
VERSION:2.0
PRODID:-//ARTIFACT//EN
CALSCALE:GREGORIAN
BEGIN:VEVENT
UID:artifact-museum-night-2026
DTSTAMP:20261018T100000Z
DTSTART:20261018T190000
DTEND:20261019T020000
SUMMARY:ARTIFACT: Museum Night
DESCRIPTION:A cinematic after-hours museum event with exhibitions, performances, talks, and guided tours.
LOCATION:The Old Gallery, Warsaw
END:VEVENT
END:VCALENDAR`;

                const blob = new Blob([icsContent], { type: 'text/calendar;charset=utf-8' });
                const url = URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = url;
                a.download = 'artifact-museum-night.ics';
                document.body.appendChild(a);
                a.click();
                document.body.removeChild(a);
                URL.revokeObjectURL(url);

                toast.className = 'toast success';
                toast.textContent = 'Calendar file downloaded!';
                toast.classList.add('show');
                setTimeout(() => {
                    toast.classList.remove('show');
                }, 3000);
            });

            // Newsletter Form
            newsletterForm.addEventListener('submit', (e) => {
                e.preventDefault();
                const email = newsletterForm.querySelector('input[type="email"]').value.trim();
                if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
                    toast.className = 'toast error';
                    toast.textContent = 'Please enter a valid email';
                    toast.classList.add('show');
                    setTimeout(() => {
                        toast.classList.remove('show');
                    }, 3000);
                    return;
                }
                toast.className = 'toast success';
                toast.textContent = 'Thank you for subscribing!';
                toast.classList.add('show');
                setTimeout(() => {
                    toast.classList.remove('show');
                }, 3000);
                newsletterForm.reset();
            });

            // FAQ Accordion
            faqItems.forEach(item => {
                const question = item.querySelector('.faq-question');
                question.addEventListener('click', () => {
                    item.classList.toggle('active');
                });
            });
        });
    </script>
</body>
</html>"}
